KVK2_DEFAULT = {"season": "", "me": 4123, "teams": {"n": 2, "assign": {}}, "kingdoms": [
    {"id": i, "group": g, "rank": r, "power": p, "kp": k, "deads": d} for i, g, r, p, k, d in KVK2_SEED]}


def kvk2_clean(d):
    """Prueft die KVK2-Daten und gibt eine bereinigte Kopie zurueck."""
    if not isinstance(d, dict) or not isinstance(d.get("kingdoms"), list):
        raise ValueError("Missing sections: kingdoms")
    out = []
    for x in d["kingdoms"][:300]:
        if not isinstance(x, dict):
            continue
        i = int(x.get("id") or 0)
        if i <= 0:
            continue
        out.append({"id": i, "group": str(x.get("group") or "")[:1].upper(),
                    **{k: max(0, int(x.get(k) or 0)) for k in ("rank", "power", "kp", "deads")}})
    ids = {x["id"] for x in out}
    me = int(d.get("me") or 0)
    t = d.get("teams") if isinstance(d.get("teams"), dict) else {}
    n = min(4, max(2, int(t.get("n") or 2)))
    assign = {}
    for k, v in (t.get("assign") or {}).items():
        try:
            if int(k) in ids and 0 <= int(v) < n:
                assign[str(int(k))] = int(v)
        except (TypeError, ValueError):
            pass
    return {"season": str(d.get("season") or "")[:60], "me": me if me in ids else (out[0]["id"] if out else 0), "kingdoms": out,
            "teams": {"n": n, "assign": assign}}


INACT_DEFAULT = {"asof": "2026-11-15 17:21", "members": [{"name": "\u02e2\u02b0Nikemo", "days": 4}]}


def inact_clean(d):
    out = []
    for m in (d.get("members") if isinstance(d, dict) else None) or []:
        try:
            nm = str(m.get("name", "")).strip()[:40]
            dy = max(3, min(999, int(m.get("days", 4))))
        except Exception:
            continue
        if nm:
            out.append({"name": nm, "days": dy})
    return {"asof": str((d or {}).get("asof", ""))[:20], "members": out}


def inact_load(db):
    try:
        raw = db.get_setting("inactive", "")
        return inact_clean(json.loads(raw)) if raw else INACT_DEFAULT
    except Exception:
        return INACT_DEFAULT


def kvk2_load(db):
    """Gespeicherte Daten; leere Eintraege der vorbelegten Kingdoms werden aus dem Screenshot-Stand gefuellt."""
    try:
        d = kvk2_clean(json.loads(db.get_setting("kvk2", "") or "null") or KVK2_DEFAULT)
    except Exception:
        return KVK2_DEFAULT
    have = {x["id"]: x for x in d["kingdoms"]}
    for seed in KVK2_DEFAULT["kingdoms"]:
        x = have.get(seed["id"])
        if x is None:
            d["kingdoms"].append(dict(seed))
        elif not (x["power"] or x["kp"] or x["deads"]):
            x.update(seed)
    return d


